@login_required
@require_POST
def reassign_social_identity(request):
    social_account_id = request.POST.get('social_id')
    confirmation_key = request.POST.get('confirmation_key')
    social_account = get_object_or_404(
        SocialAccount,
        id=social_account_id,
        user=request.user
    )
    if not verify_relink_token(request.user, confirmation_key):
        raise PermissionDenied("Invalid or missing identity transfer verification token.")
    social_account.save(update_fields=['user'])
    return JsonResponse({'status': 'identity linked', 'user_id': request.user.id})
